import pandas as pd

# First, check what columns exist in the enterprise_data table
col_check = execute_sql_query("SELECT * FROM enterprise_data LIMIT 1")
available_columns = col_check.columns.tolist()
print(f"Available columns: {available_columns}")

# List of column paths to check
column_paths = {
    'Previous_Employers': '[Employee Previous Employer[Previous Employer Name][Previous Job Title][Start Date][End Date]]',
    'Competency_Ratings': '[Employee Master[Competency Ratings][Rating]]',
    'Leave_Records': '[Leave Details[Leave Type]]',
    'Objectives': '[Employee Master[Objectives][Objective]]'
}

# Initialize employee data
all_emp_df = execute_sql_query('SELECT "[Employee Master[Employee Name]]" FROM enterprise_data')
all_employees = all_emp_df['[Employee Master[Employee Name]]'].tolist()
employee_counts = {}

for emp in all_employees:
    employee_counts[emp] = {'Employee': emp, 'Competency_Ratings': 0, 'Leave_Records': 0, 'Objectives': 0, 'Previous_Employers': 0}

# Process each column type if it exists
for count_type, col_path in column_paths.items():
    if col_path in available_columns:
        try:
            # Build query with proper DuckDB UNNEST syntax
            query = f"""
            SELECT 
                "[Employee Master[Employee Name]]" as Employee_Name,
                COUNT(*) as Count_Value
            FROM enterprise_data, 
            UNNEST({col_path}) AS t(rec)
            GROUP BY "[Employee Master[Employee Name]]"
            """
            df = execute_sql_query(query)

            for idx, row in df.iterrows():
                emp = row['Employee_Name']
                if emp in employee_counts:
                    employee_counts[emp][count_type] = int(row['Count_Value'])
            print(f"Query successful for: {count_type}")
        except Exception as e:
            print(f"Query failed for {count_type}: {e}")
    else:
        print(f"Column not available: {count_type} ({col_path})")

# Build result table
result_rows = []
for emp_name, counts in employee_counts.items():
    line = f"- {counts['Employee']}: {counts['Competency_Ratings']} competency ratings, {counts['Leave_Records']} leave records, {counts['Objectives']} objectives, {counts['Previous_Employers']} previous employers"
    result_rows.append(line)

result_table = '\n'.join(result_rows)

# Create summary message
summary = f"""Employee Counts (Note: Columns checked against schema):
{result_table}

Total employees processed: {len(employee_counts)}
Columns available in schema: {', '.join(available_columns)}
"""

result = {'type': 'string', 'value': summary}
